window.SITE_NATURE = [{"id":"parcul-national-retezat","name":"Parcul Național Retezat","category":{"ro":"Parc național","en":"National park"},"area":"Țara Hațegului","townId":"hateg","coords":[45.3583,22.875],"hasReviews":true,"images":["images/retezat-bucura.jpg"],"photoCredit":{"author":"Daniel Ighișan","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Retezat_View_over_Bucura_lake.jpg"},"ro":{"tagline":"Cel mai vechi parc național din România (1935), cu peste 80 de lacuri glaciare.","description":["Retezat a fost declarat parc național în 1935, fiind cel mai vechi din țară. Adăpostește Lacul Bucura — cel mai mare lac glaciar din România (2.030 m altitudine) — și Vârful Peleaga (2.509 m), cel mai înalt punct al masivului.","Zona centrală e rezervație științifică strictă; traseele de creastă și cele spre lacurile glaciare sunt printre cele mai spectaculoase din Carpați."],"facts":[{"label":"Înființat","value":"1935 (cel mai vechi parc național din România)"},{"label":"Cel mai mare lac","value":"Lacul Bucura, 2.030 m altitudine"},{"label":"Cel mai înalt vârf","value":"Vf. Peleaga, 2.509 m"}]},"en":{"name":"Retezat National Park","tagline":"Romania's oldest national park (1935), with over 80 glacial lakes.","description":["Retezat was declared a national park in 1935, the oldest in the country. It holds Lake Bucura — Romania's largest glacial lake (2,030 m altitude) — and Peleaga Peak (2,509 m), the massif's highest point.","The core area is a strict scientific reserve; the ridge trails and those leading to the glacial lakes are among the most spectacular in the Carpathians."],"facts":[{"label":"Established","value":"1935 (Romania's oldest national park)"},{"label":"Largest lake","value":"Lake Bucura, 2,030 m altitude"},{"label":"Highest peak","value":"Peleaga Peak, 2,509 m"}]}},{"id":"pestera-bolii","name":"Peștera Bolii","category":{"ro":"Peșteră","en":"Cave"},"area":"Bănița","townId":"banita","coords":[45.4539,23.3183],"hasReviews":true,"season":"tot-anul","images":["images/pestera-bolii-portal.jpg"],"photoCredit":{"author":"mihai moise","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Pestera_Boli_-_panoramio.jpg"},"ro":{"tagline":"Peșteră-râu de 455 m, amenajată cu iluminat electric, la marginea Parcului Natural Grădiștea Muncelului-Cioclovina.","description":["Peștera Bolii se traversează pe jos, urmând pârâul Galbina care iese printr-un portal impresionant, de 20 m lățime și 10 m înălțime. E una dintre puținele peșteri din județ complet vizitabile de-a lungul cursului de apă.","Se află la câțiva kilometri de Petroșani, în apropierea Cheilor Băniței."],"facts":[{"label":"Lungime","value":"455 m"},{"label":"Portal","value":"20 m lățime, 10 m înălțime"},{"label":"Amenajare","value":"Iluminat electric, traversabilă pe cursul râului Galbina"}]},"en":{"name":"Bolii Cave","tagline":"A 455 m river cave with electric lighting, on the edge of the Grădiștea Muncelului-Cioclovina Natural Park.","description":["Bolii Cave is walked through following the Galbina creek, which exits through an impressive 20 m wide, 10 m high portal. It's one of the few caves in the county that can be fully walked along its watercourse.","It lies a few kilometres from Petroșani, near the Bănița Gorges."],"facts":[{"label":"Length","value":"455 m"},{"label":"Portal","value":"20 m wide, 10 m high"},{"label":"Facilities","value":"Electric lighting, walkable along the Galbina stream"}]}},{"id":"cheile-banitei","name":"Cheile Băniței","category":{"ro":"Chei","en":"Gorge"},"area":"Bănița","townId":"banita","hasReviews":true,"images":["images/cheile-banitei.jpg"],"photoCredit":{"author":"Muzeul Civilizației Dacice și Romane Deva","license":"material de promovare al instituției","source":"https://www.facebook.com/photo/?fbid=1493112846164749","sourceLabel":"Facebook"},"ro":{"tagline":"Defileu calcaros de cca. 300 m, cu pereți de 10-15 m, traversat de DN66 și de calea ferată Simeria–Petroșani.","description":["Cheile Băniței sunt un defileu calcaros pe drumul dintre Petroșani și restul județului, chiar în zona Peșterii Bolii. Pereții abrupți și drumul/calea ferată care șerpuiesc prin chei fac din traseu unul dintre cele mai spectaculoase din județ, chiar și văzut din mașină sau tren.","Pe jos, traseul prin chei se face parțial prin albia râului — recomandat cu încălțăminte adecvată, apa ajunge de obicei până la gleznă, pe alocuri până la genunchi."],"facts":[{"label":"Lungime","value":"cca. 300 m, pereți de 10-15 m înălțime"},{"label":"Acces","value":"DN66 Simeria–Petroșani, în apropierea Peșterii Bolii"}]},"en":{"name":"Bănița Gorge","tagline":"A limestone gorge about 300 m long, with 10-15 m walls, crossed by the DN66 road and the Simeria–Petroșani railway.","description":["The Bănița Gorge is a limestone gorge on the road between Petroșani and the rest of the county, right by Bolii Cave. The steep walls and the road/railway winding through the gorge make it one of the county's most spectacular routes, even seen from a car or train.","On foot, the route through the gorge partly follows the riverbed — proper footwear is recommended, as the water usually reaches ankle height, sometimes knee height."],"facts":[{"label":"Length","value":"approx. 300 m, 10-15 m walls"},{"label":"Access","value":"DN66 Simeria–Petroșani, near Bolii Cave"}]}},{"id":"parangul-mare","name":"Vârful Parângul Mare","category":{"ro":"Vârf montan","en":"Mountain peak"},"area":"Parâng","coords":[45.3411,23.5406],"hasReviews":true,"season":"vara","images":["images/parangul-mare-varf.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Varful_Parangul_Mare_(2519m)_-_panoramio.jpg"},"ro":{"tagline":"2.519 m — cel mai înalt vârf din Munții Parâng, accesibil cu telescaunul din Petroșani plus un traseu pe creastă.","description":["Parângul Mare este acoperișul masivului Parâng și un punct de belvedere spre Retezat, Șureanu și Valea Jiului. Telescaunul din Petroșani urcă spre platoul Parâng, de unde pornește traseul de creastă spre vârf."],"facts":[{"label":"Altitudine","value":"2.519 m"},{"label":"Cum ajungi","value":"Telescaun din Petroșani + traseu de creastă"}]},"en":{"name":"Parângul Mare Peak","tagline":"2,519 m — the highest peak in the Parâng Mountains, reachable by the Petroșani chairlift plus a ridge trail.","description":["Parângul Mare is the roof of the Parâng massif and a viewpoint over Retezat, Șureanu and the Jiu Valley. The chairlift from Petroșani goes up to the Parâng plateau, from where the ridge trail to the peak starts."],"facts":[{"label":"Altitude","value":"2,519 m"},{"label":"Getting there","value":"Chairlift from Petroșani + ridge trail"}]}},{"id":"padurea-bicolora-petrila","name":"Pădurea Bicoloră","category":{"ro":"Fenomen natural","en":"Natural phenomenon"},"area":"Petrila","townId":"petrila","coords":[45.4717,23.4081],"hasReviews":true,"season":"toamna","images":["images/padurea-bicolora-petrila.jpg"],"photoCredit":{"author":"Andrei Bunzac / OMD Valea Jiului","license":"material de promovare al instituției","source":"https://www.facebook.com/61579481461946/posts/122180287496982715","sourceLabel":"Facebook"},"ro":{"tagline":"Un deal parcă tăiat în două culori, la Cheile Tăii, lângă Petrila — molid mereu verde pe o parte, fag auriu pe cealaltă.","description":["Pădurea Bicoloră s-a format acum aproape jumătate de secol, când o jumătate din versant a fost defrișată și replantată cu molid, în timp ce cealaltă jumătate a rămas pădure naturală de fag. Linia dintre cele două tipuri de vegetație a rămas aproape perfect dreaptă, de la vârful dealului până la vale.","Contrastul se vede tot anul — molidul rămâne verde, fagul își schimbă culoarea — dar cel mai spectaculos e toamna, timp de câteva săptămâni, când frunzișul de fag devine auriu-roșcat. Locul se află pe traseul spre Cheile Tăii, rezervație naturală protejată, la câțiva kilometri de Petrila."],"facts":[{"label":"Acces","value":"Câțiva kilometri de Petrila, pe drumul spre Cheile Tăii"},{"label":"Cel mai bun sezon","value":"Toamna, câteva săptămâni, cât fagul se colorează"},{"label":"Zonă protejată","value":"Rezervația naturală Cheile Tăii (2 ha)"}]},"en":{"name":"Two-Coloured Forest","tagline":"A hillside that looks cut in two colours, at the Tăia Gorges near Petrila — evergreen spruce on one side, golden beech on the other.","description":["Pădurea Bicoloră (the \"Two-Coloured Forest\") formed nearly half a century ago, when one half of the slope was cleared and replanted with spruce, while the other half stayed natural beech forest. The line between the two kinds of vegetation stayed almost perfectly straight, from the hilltop down to the valley.","The contrast is visible year-round — the spruce stays green, the beech changes colour — but it's most spectacular in autumn, for a few weeks, when the beech foliage turns golden-rust. The spot lies on the way to the Tăia Gorges, a protected nature reserve, a few kilometres from Petrila."],"facts":[{"label":"Access","value":"A few kilometres from Petrila, on the road to the Tăia Gorges"},{"label":"Best season","value":"Autumn, a few weeks while the beech turns colour"},{"label":"Protected area","value":"Tăia Gorges nature reserve (2 ha)"}]}},{"id":"pasul-vulcan","name":"Pasul Vulcan","category":{"ro":"Trecătoare montană","en":"Mountain pass"},"area":"Vâlcan","hasReviews":true,"season":"tot-anul","images":["images/pasul-vulcan-statiune.jpg"],"photoCredit":{"author":"Manolache Alex","license":"CC BY 2.0","source":"https://www.flickr.com/photos/118306345@N06/12672007465","sourceLabel":"Flickr"},"ro":{"tagline":"Trecătoare istorică de 1.621 m care leagă Valea Jiului de Oltenia.","description":["Pasul Vulcan este o trecătoare montană aflată la altitudinea de 1.621 m, în partea de est a Munților Vâlcan, la granița dintre județele Hunedoara și Gorj. Face legătura între Depresiunea Petroșani și depresiunea subcarpatică Târgu Jiu – Câmpu Mare, pe drumul județean DJ664 (Vulcan – Schela).","Drumul peste pas urmează un traseu folosit din antichitate, străbătut istoric de Mihai Viteazul în 1600, în drumul său spre Viena. În septembrie 1916, pasul a fost și scena unor lupte între trupele române și cele germano-austro-ungare, în timpul Primului Război Mondial."],"facts":[{"label":"Altitudine","value":"1.621 m"},{"label":"Leagă","value":"județele Hunedoara și Gorj"},{"label":"Drum de acces","value":"DJ664, parțial nemodernizat"}]},"en":{"name":"Vulcan Pass","tagline":"A historic 1,621 m pass linking the Jiu Valley to Oltenia.","description":["Vulcan Pass is a mountain pass at 1,621 m altitude, in the eastern Vâlcan Mountains, on the border between Hunedoara and Gorj counties. It connects the Petroșani Depression with the Târgu Jiu – Câmpu Mare sub-Carpathian depression, via county road DJ664 (Vulcan–Schela).","The road over the pass follows a route used since antiquity, historically crossed by Prince Michael the Brave in 1600, on his way to Vienna. In September 1916, the pass was also the site of fighting between Romanian and German/Austro-Hungarian troops during World War I."],"facts":[{"label":"Altitude","value":"1,621 m"},{"label":"Connects","value":"Hunedoara and Gorj counties"},{"label":"Access road","value":"DJ664, partly unpaved"}]}},{"id":"jiet-groapa-seaca","name":"Cheile Jiețului – Groapa Seacă","category":{"ro":"Rezervație naturală","en":"Nature reserve"},"area":"Parâng","hasReviews":true,"season":"vara","images":["images/jiet-groapa-seaca.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Indicatoare_turistice_Cabana_Groapa_Seac%C4%83_-_panoramio.jpg"},"ro":{"tagline":"Chei sălbatice și izvoarele Jiețului, poartă naturală spre inima Parângului.","description":["Rezervația Cheile Jiețului este o arie naturală protejată de interes național (categoria IV IUCN), cu o suprafață de 10 ha, situată pe versantul drept al Munților Parâng, pe teritoriul orașului Petrila. Aici apele Jiețului au săpat chei abrupte și înguste, cu stânci acoperite de licheni și vegetație de pădure montană; rezervația a fost instituită în 1995 și declarată oficial în 2000.","În amonte, Cabana Groapa Seacă (~1.220 m) este un punct de plecare cunoscut pentru trasee spre Vârful Parângul Mare, Lacul Mija și alte obiective din masiv, fiind una dintre porțile clasice de acces în Parângul hunedorean."],"facts":[{"label":"Suprafață rezervație","value":"10 ha"},{"label":"Statut","value":"arie protejată, categoria IV IUCN (din 1995/2000)"},{"label":"Altitudine Cabana Groapa Seacă","value":"~1.220 m"}]},"en":{"name":"Jieț Gorge – Groapa Seacă","tagline":"Wild gorges and the springs of the Jieț, a natural gateway into the Parâng massif.","description":["The Jieț Gorge reserve is a nationally protected natural area (IUCN category IV), covering 10 ha, on the right slope of the Parâng Mountains, within the territory of Petrila town. Here the Jieț river has carved steep, narrow gorges with lichen-covered rock walls and mountain forest vegetation; the reserve was established in 1995 and officially declared in 2000.","Further upstream, Groapa Seacă Hut (~1,220 m) is a well-known starting point for trails to Parângul Mare Peak, Lake Mija and other landmarks in the massif, one of the classic access gates into the Hunedoara side of the Parâng Mountains."],"facts":[{"label":"Reserve area","value":"10 ha"},{"label":"Status","value":"protected area, IUCN category IV (since 1995/2000)"},{"label":"Groapa Seacă Hut altitude","value":"~1,220 m"}]}},{"id":"campu-lui-neag","name":"Câmpu lui Neag","category":{"ro":"Zonă montană","en":"Mountain area"},"area":"Uricani","townId":"uricani","hasReviews":true,"season":"tot-anul","images":["images/campu-lui-neag.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:C%C3%A2mpu_lui_Neag,_Hunedoara.JPG"},"ro":{"tagline":"Satul momârlanilor de la poalele Retezatului, poartă spre Parâng și Retezat.","description":["Câmpu lui Neag este o localitate din componența orașului Uricani, așezată în sud-vestul județului Hunedoara, la poalele Munților Retezat, fiind considerată una dintre porțile de acces spre Parcul Național Retezat. Zona păstrează tradițiile comunității momârlanilor, locuitorii statornici ai Văii Jiului.","Accesul se face din Petroșani sau din Târgu Jiu, pe DN66A, pe traseul Vulcan – Lupeni – Uricani – Câmpu lui Neag, pe o distanță de circa 40 km. De aici pornesc numeroase trasee turistice spre lacurile, cheile și vârfurile din Munții Retezat și Parâng."],"facts":[{"label":"Distanță de Petroșani","value":"~40 km (DN66A)"},{"label":"Poziție","value":"poalele Munților Retezat, orașul Uricani"},{"label":"Specific local","value":"comunitatea tradițională a momârlanilor"}]},"en":{"tagline":"The Momârlani mountain village at the foot of the Retezat, gateway to Parâng and Retezat.","description":["Câmpu lui Neag is a village within Uricani town, in the southwestern part of Hunedoara County, at the foot of the Retezat Mountains, considered one of the gateways to Retezat National Park. The area preserves the traditions of the Momârlani, the long-settled mountain community of the Jiu Valley.","Access is from Petroșani or Târgu Jiu on road DN66A, via Vulcan – Lupeni – Uricani – Câmpu lui Neag, about 40 km. From here, numerous trails lead to lakes, gorges and peaks in the Retezat and Parâng mountains."],"facts":[{"label":"Distance from Petroșani","value":"~40 km (DN66A)"},{"label":"Location","value":"foot of the Retezat Mountains, Uricani town"},{"label":"Local character","value":"traditional Momârlani community"}]}},{"id":"cheile-buta","name":"Cheile Buții","category":{"ro":"Chei","en":"Gorge"},"area":"Vâlcan","hasReviews":true,"season":"vara","images":["images/cheile-buta.jpg"],"photoCredit":{"author":"Complexul Turistic Cheile Butii","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=100057251688574","sourceLabel":"Facebook"},"ro":{"tagline":"Chei calcaroase spectaculoase, printre cele mai frumoase arii protejate din Munții Vâlcan.","description":["Cheile Buții sunt săpate de râul Buta (afluent al Jiului de Vest) în calcare jurasice, la granița dintre județele Hunedoara și Gorj, în Munții Vâlcan. Pereții abrupți, care ajung până la aproximativ 100 m înălțime, adăpostesc peșteri, izvoare și cascade, zona fiind considerată una dintre cele mai spectaculoase arii protejate din această parte a Europei.","Punctul de plecare pentru vizitarea cheilor este Cabana Buta, aflată la altitudinea de 1.580 m, pe creasta Piule–Pleșa, cu priveliști spre Oslea și Munții Vâlcan. Accesul pe jos, marcat cu bandă/cruce roșie, durează aproximativ 4 ore de la șoseaua DN66A."],"facts":[{"label":"Altitudine Cabana Buta","value":"1.580 m"},{"label":"Rocă","value":"calcar jurasic"},{"label":"Acces pe jos","value":"~4 ore de la DN66A, marcaj cruce roșie"}]},"en":{"name":"Buta Gorges","tagline":"Spectacular limestone gorges, among the most beautiful protected areas in the Vâlcan Mountains.","description":["The Buta Gorges (Cheile Buții) were carved by the Buta river (a tributary of the Jiul de Vest) through Jurassic limestone, on the Hunedoara–Gorj county border, in the Vâlcan Mountains. The steep walls, reaching about 100 m in height, shelter caves, springs and waterfalls, and the area is considered one of the most spectacular protected areas in this part of Europe.","The starting point for visiting the gorges is Buta Hut, at 1,580 m altitude, on the Piule–Pleșa ridge, with views toward Oslea and the Vâlcan Mountains. The hike, marked with a red cross trail, takes about 4 hours from the DN66A road."],"facts":[{"label":"Buta Hut altitude","value":"1,580 m"},{"label":"Rock type","value":"Jurassic limestone"},{"label":"Hiking access","value":"~4 hours from DN66A, red cross marking"}]}},{"id":"valea-iarului","name":"Valea Iarului","category":{"ro":"Vale montană","en":"Mountain valley"},"area":"Uricani","townId":"uricani","hasReviews":true,"season":"vara","images":["images/valea-iarului.jpg"],"photoCredit":{"author":"Camping Valea Iarului","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=100069745995452","sourceLabel":"Facebook"},"ro":{"tagline":"Vale montană retrasă lângă Câmpușel, punct de plecare pentru drumeții și camping montan.","description":["Valea Iarului este o vale montană situată în zona Câmpușel, la aproximativ 29 km de orașul Uricani, pe versantul dinspre Retezat al munților din sud-vestul județului. Zona este relativ sălbatică și puțin populată, cu acces facilitat de câteva trasee marcate, de dificultate moderată spre dificilă.","Aici funcționează Camping Valea Iarului, o amenajare de tip glamping cu corturi încălzite montate pe platforme de lemn, punct de popas apreciat de drumeți înainte de a urca spre creste."],"facts":[{"label":"Zonă","value":"Câmpușel, orașul Uricani"},{"label":"Distanță de Uricani","value":"~29 km"},{"label":"Facilități","value":"camping/glamping, trasee de drumeție marcate"}]},"en":{"name":"Iarului Valley","tagline":"A secluded mountain valley near Câmpușel, a base for hiking and mountain camping.","description":["Valea Iarului is a mountain valley in the Câmpușel area, about 29 km from the town of Uricani, on the Retezat side of the mountains in the county's south-west. The area is relatively wild and sparsely populated, reached via several marked trails of moderate to difficult grade.","Camping Valea Iarului operates here, a glamping-style site with heated tents on wooden platforms, a popular stop for hikers before heading up to the ridges."],"facts":[{"label":"Area","value":"Câmpușel, Uricani town"},{"label":"Distance from Uricani","value":"~29 km"},{"label":"Facilities","value":"camping/glamping, marked hiking trails"}]}},{"id":"drum-transmontan-uricani-runcu","name":"Drumul transmontan Uricani – Runcu","category":{"ro":"Drum montan turistic","en":"Scenic mountain road"},"area":"Uricani","townId":"uricani","hasReviews":true,"season":"vara","images":["images/drum-transmontan-uricani-runcu.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cheile_Sohodolului.JPG"},"ro":{"tagline":"Drum montan nou-asfaltat care leagă Uricani de Gorj prin Cheile Sohodolului, la 830 m altitudine.","description":["Finalizat pe partea hunedoreană în noiembrie 2025, drumul transmontan Uricani–Runcu leagă județele Hunedoara și Gorj printr-o zonă montană cu peisaje spectaculoase, trecând pe lângă Cheile Sohodolului și barajul de la Valea de Pești, la o altitudine maximă de circa 830 m. Lucrarea, în valoare de peste 44,4 milioane de lei, a fost finanțată prin Programul Anghel Saligny, de UAT Uricani în parteneriat cu Consiliul Județean Hunedoara.","Pe partea dinspre Gorj lucrările mai au nevoie de până la doi ani pentru finalizare, dar noul acces deschide deja drumul spre Cheile Sohodolului și lacul Valea de Pești și a atras primele investiții în cabane și pensiuni din zonă."],"facts":[{"label":"Leagă","value":"Uricani (Hunedoara) – Runcu (Gorj)"},{"label":"Altitudine maximă","value":"~830 m"},{"label":"Finalizat (partea HD)","value":"noiembrie 2025"},{"label":"Acces spre","value":"Cheile Sohodolului, lacul Valea de Pești"}]},"en":{"name":"Uricani – Runcu mountain road","tagline":"A newly-paved mountain road linking Uricani to Gorj county through the Sohodol Gorges, at 830 m altitude.","description":["Completed on the Hunedoara side in November 2025, the Uricani–Runcu mountain road links Hunedoara and Gorj counties through a mountain area with spectacular scenery, passing the Sohodol Gorges and the Valea de Pești dam, at a maximum altitude of about 830 m. The works, worth over 44.4 million lei, were funded through the Anghel Saligny Programme, carried out by Uricani local authority in partnership with Hunedoara County Council.","On the Gorj side, works still need up to two years to finish, but the new access already opens the way to the Sohodol Gorges and Lake Valea de Pești, and has already drawn the area's first guesthouse and cabin investments."],"facts":[{"label":"Connects","value":"Uricani (Hunedoara) – Runcu (Gorj)"},{"label":"Maximum altitude","value":"~830 m"},{"label":"Completed (HD side)","value":"November 2025"},{"label":"Access to","value":"The Sohodol Gorges, Lake Valea de Pești"}]}},{"id":"lacul-cincis","name":"Lacul Cinciș","category":{"ro":"Lac de acumulare","en":"Reservoir lake"},"area":"Hunedoara","townId":"hunedoara","coords":[45.69,22.86],"hasReviews":true,"season":"vara","images":["images/lacul-cincis.jpg"],"photoCredit":{"author":"Raydu18","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Cincis.jpg"},"ro":{"tagline":"Lac de acumulare lângă Hunedoara, cu plaje, pescuit și una dintre cele mai mari suprafețe de apă artificiale din Transilvania.","description":["Lacul Cinciș este un lac de acumulare format pe cursul râului Cerna, lângă satul Teliucu Inferior, la circa 15 km de Hunedoara, printr-un baraj construit la începutul anilor 1960 pentru alimentarea cu apă a combinatului siderurgic și a orașului. Cu o suprafață de circa 867 ha și o adâncime maximă de 48 m, este unul dintre cele mai mari lacuri artificiale din Transilvania.","Malul nordic, cu plaje, contrastează cu malul sudic, împădurit și deluros. Zona s-a dezvoltat ca stațiune de interes local, cu campinguri, moteluri și pensiuni, iar lacul rămâne căutat pentru pescuit (crap, știucă, amur, șalău, caras) și înot în sezonul cald (iunie–august)."],"facts":[{"label":"Râu / baraj","value":"Lac de acumulare pe Cerna, amenajat la începutul anilor 1960"},{"label":"Suprafață","value":"~867 ha (8,67 km²)"},{"label":"Adâncime maximă","value":"48 m"},{"label":"Sezon turistic","value":"iunie–august, temperatura apei ~18°C"},{"label":"Pești","value":"crap, știucă, amur, șalău, caras"}]},"en":{"name":"Lake Cinciș","tagline":"A reservoir lake near Hunedoara, with beaches, fishing and one of Transylvania's largest artificial water surfaces.","description":["Lake Cinciș is a reservoir lake formed on the Cerna river near the village of Teliucu Inferior, about 15 km from Hunedoara, after a dam was built there in the early 1960s to supply water to the steel works and the city. Covering around 867 ha with a maximum depth of 48 m, it is one of the largest artificial lakes in Transylvania.","The northern shore, lined with beaches, contrasts with the wooded, hilly southern shore. The area developed into a local resort, with campsites, motels and guesthouses, and the lake remains popular for fishing (carp, pike, amur, pike-perch, crucian carp) and swimming in the warm season (June–August)."],"facts":[{"label":"River / dam","value":"Reservoir lake on the Cerna, built in the early 1960s"},{"label":"Surface area","value":"~867 ha (8.67 km²)"},{"label":"Maximum depth","value":"48 m"},{"label":"Tourist season","value":"June–August, water temperature ~18°C"},{"label":"Fish species","value":"carp, pike, amur, pike-perch, crucian carp"}]}},{"id":"padurea-bejan","name":"Pădurea Bejan","category":{"ro":"Rezervație naturală","en":"Nature reserve"},"area":"Deva","townId":"deva","coords":[45.8517,22.8889],"hasReviews":true,"season":"tot-anul","images":["images/placeholder.svg"],"ro":{"tagline":"Rezervație forestieră de 70 ha lângă Deva, unde coexistă opt din cele nouă specii native de stejar din România.","description":["Pădurea Bejan este o rezervație naturală de tip forestier declarată prin Legea nr. 5 din 6 martie 2000, cu o suprafață de 70 ha, situată pe teritoriul administrativ al Devei, pe drumul județean DJ708E dinspre Almașu Sec. Este încadrată în categoria IV IUCN (arie de gestionare a habitatelor/speciilor).","Valoarea ei științifică vine din coexistența a opt din cele nouă specii native de stejar din România, care au dat naștere, de-a lungul timpului, unor hibrizi rar întâlniți în altă parte. Printre plantele rare identificate aici se numără frăsinelul (Dictamnus albus), iar dintre animale — căprior, jder, iepure de câmp, șarpele lui Esculap și buhaiul de baltă cu burta galbenă."],"facts":[{"label":"Suprafață","value":"70 ha"},{"label":"Statut","value":"Rezervație naturală (Legea nr. 5/2000), categoria IUCN IV"},{"label":"Valoare științifică","value":"8 din cele 9 specii native de stejar din România"},{"label":"Acces","value":"DJ708E, lângă Deva"}]},"en":{"name":"Bejan Forest","tagline":"A 70 ha forest reserve near Deva, home to eight of Romania's nine native oak species growing side by side.","description":["Pădurea Bejan is a forest-type nature reserve declared under Law no. 5 of 6 March 2000, covering 70 ha within Deva's administrative territory, on county road DJ708E from Almașu Sec. It is classified as IUCN category IV (habitat/species management area).","Its scientific value comes from the coexistence of eight of Romania's nine native oak (Quercus) species, which over time have produced hybrids rarely found elsewhere. Rare plants recorded here include fraxinella (Dictamnus albus), while the fauna includes roe deer, pine marten, European hare, the Aesculapian snake and the yellow-bellied toad."],"facts":[{"label":"Area","value":"70 ha"},{"label":"Status","value":"Nature reserve (Law no. 5/2000), IUCN category IV"},{"label":"Scientific value","value":"8 of Romania's 9 native oak species"},{"label":"Access","value":"DJ708E, near Deva"}]}},{"id":"parcul-dendrologic-simeria","name":"Parcul Dendrologic Simeria","category":{"ro":"Parc dendrologic","en":"Dendrological park"},"area":"Simeria","townId":"simeria","coords":[45.8569,23.011],"hasReviews":true,"season":"tot-anul","images":["images/parcul-dendrologic-simeria.jpg"],"photoCredit":{"author":"Roxana Stamate","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lacul_din_parcul_dendrologic_Simeria.jpg"},"ro":{"tagline":"Cel mai vechi și mai mare parc dendrologic din România, cu peste 2.100 de specii de arbori și arbuști pe cca 70 de hectare.","description":["Arboretumul Simeria s-a dezvoltat din parcul conacului familiei Gyulay, documentat din 1763, pe malul stâng al Mureșului. După naționalizare, în 1949 a fost transformat oficial în parc dendrologic și dat în administrarea unei stațiuni de cercetare silvică, funcție păstrată și azi.","Colecția, adunată din Europa, America de Nord și Asia, este considerată una dintre cele mai valoroase din România și cuprinde exemplare rare, printre care arbori seculari. Parcul e monument al naturii și se vizitează cu bilet de intrare, pe alei amenajate."],"facts":[{"label":"Suprafață","value":"cca 70 ha"},{"label":"Specii","value":"peste 2.100 de specii de arbori și arbuști"},{"label":"Documentat din","value":"1763 (parcul conacului Gyulay)"},{"label":"Devenit parc dendrologic","value":"1949"}]},"en":{"name":"Simeria Arboretum","tagline":"Romania's oldest and largest dendrological park, with over 2,100 tree and shrub species on about 70 hectares.","description":["Simeria Arboretum grew out of the Gyulay family manor park, documented since 1763, on the left bank of the Mureș river. After nationalisation, it was officially turned into a dendrological park in 1949 and placed under a forestry research station, a role it still holds today.","The collection, gathered from Europe, North America and Asia, is considered one of Romania's most valuable and includes rare specimens, among them centuries-old trees. The park is a protected natural monument and is visited on marked paths with an entrance ticket."],"facts":[{"label":"Area","value":"about 70 ha"},{"label":"Species","value":"over 2,100 tree and shrub species"},{"label":"Documented since","value":"1763 (the Gyulay manor park)"},{"label":"Became a dendrological park","value":"1949"}]}},{"id":"geoparcul-tara-hategului","name":"Geoparcul UNESCO Țara Hațegului","category":{"ro":"Geoparc UNESCO","en":"UNESCO Global Geopark"},"area":"Țara Hațegului","townId":"hateg","coords":[45.6103,22.9477],"hasReviews":true,"season":"tot-anul","images":["images/geoparc-hateg-magyarosaurus.jpg"],"photoCredit":{"author":"N.Cayla","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Magyarosaurus_dacus.jpg"},"ro":{"tagline":"Geoparcul dinozaurilor pitici: peste 1.000 km² din Țara Hațegului, recunoscut internațional din 2005 și Geoparc Global UNESCO din 2015.","description":["Geoparcul cuprinde teritoriul orașului Hațeg și al comunelor Baru, Densuș, General Berthelot, Pui, Răchitova, Râu de Mori, Sarmizegetusa, Sălașu de Sus, Sântămăria-Orlea și Totești. A fost declarat arie protejată în 2004, a intrat în 2005 în Rețeaua Europeană și în Rețeaua Globală a Geoparcurilor — primul geoparc din Sud-Estul Europei cu acest statut — și este Geoparc Global UNESCO din 2015. Este administrat de Universitatea din București.","Vedetele geoparcului sunt dinozaurii pitici din Cretacicul târziu, de acum circa 70 de milioane de ani, când zona era o insulă — „Insula Hațegului”. Aici au fost găsite cuiburi cu ouă și embrioni de dinozauri, mamifere contemporane cu dinozaurii și reptila zburătoare Hatzegopteryx. Primele oase de dinozaur au fost descoperite în 1895 pe domeniul familiei Nopcsa, iar baronul Franz Nopcsa a formulat pornind de la ele teoria nanismului insular.","Geoparcul se vizitează prin „casele geoparcului”, centre de vizitare și interpretare: Casa Geoparcului din Hațeg (cu reconstituirea dinozaurului Balaur bondoc), Casa pentru Știință și Artă din General Berthelot (cu un Magyarosaurus dacus în mărime naturală în curte și cuiburi originale cu ouă de dinozaur), Casa Dinozaurilor Pitici din Sânpetru și Casa Vulcanilor din Densuș. Programul diferă în funcție de sezon, iar unele case se vizitează doar cu programare."],"facts":[{"label":"Statut","value":"Geoparc Global UNESCO (2015); în rețelele europeană și globală a geoparcurilor din 2005"},{"label":"Suprafață","value":"peste 1.000 km² — orașul Hațeg și 10 comune"},{"label":"Administrator","value":"Universitatea din București"},{"label":"Fosile celebre","value":"Magyarosaurus, Balaur bondoc, Hatzegopteryx, cuiburi cu ouă de dinozaur"},{"label":"Centre de vizitare","value":"Hațeg, General Berthelot, Sânpetru, Densuș"}]},"en":{"name":"Hațeg Country UNESCO Geopark","tagline":"The dwarf dinosaur geopark: over 1,000 km² of Țara Hațegului, internationally recognised since 2005 and a UNESCO Global Geopark since 2015.","description":["The geopark covers the town of Hațeg and the communes of Baru, Densuș, General Berthelot, Pui, Răchitova, Râu de Mori, Sarmizegetusa, Sălașu de Sus, Sântămăria-Orlea and Totești. It was declared a protected area in 2004, joined the European and Global Geoparks Networks in 2005 — the first geopark in South-East Europe to do so — and has been a UNESCO Global Geopark since 2015. It is managed by the University of Bucharest.","Its stars are the dwarf dinosaurs of the Late Cretaceous, some 70 million years ago, when the area was an island — \"Hațeg Island\". Finds here include dinosaur nests with eggs and embryos, mammals that lived alongside the dinosaurs and the flying reptile Hatzegopteryx. The first dinosaur bones were discovered in 1895 on the Nopcsa family estate, and Baron Franz Nopcsa built on them his theory of insular dwarfism.","The geopark is explored through its \"geopark houses\", visitor and interpretation centres: The Geopark House in Hațeg (with a reconstruction of the dinosaur Balaur bondoc), the House of Science and Art in General Berthelot (with a life-size Magyarosaurus dacus in the yard and original nests with dinosaur eggs), the House of Dwarf Dinosaurs in Sânpetru and the House of Volcanoes in Densuș. Opening hours vary with the season, and some houses can only be visited by appointment."],"facts":[{"label":"Status","value":"UNESCO Global Geopark (2015); in the European and Global Geoparks Networks since 2005"},{"label":"Area","value":"over 1,000 km² — the town of Hațeg and 10 communes"},{"label":"Managed by","value":"University of Bucharest"},{"label":"Famous fossils","value":"Magyarosaurus, Balaur bondoc, Hatzegopteryx, dinosaur egg nests"},{"label":"Visitor centres","value":"Hațeg, General Berthelot, Sânpetru, Densuș"}]}},{"id":"lacul-gura-apelor","name":"Lacul Gura Apelor","category":{"ro":"Lac de acumulare","en":"Reservoir lake"},"area":"Parcul Național Retezat","townId":"rau-de-mori","coords":[45.3392,22.7217],"hasReviews":true,"season":"vara","images":["images/lacul-gura-apelor.jpg"],"photoCredit":{"author":"Dezidor","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lacul_Gura_Apei.jpg"},"ro":{"tagline":"Lacul de munte din spatele celui mai înalt baraj din România (168 m), la intrarea în Parcul Național Retezat.","description":["Lacul Gura Apelor s-a format în spatele barajului cu același nume, construit între 1975 și 1986 pe Râul Mare, la confluența cu Lăpușnicul Mare, Lăpușnicul Mic și râul Șes, la aproximativ 40 de km de Hațeg. Barajul, din anrocamente cu nucleu de argilă, are 168 m înălțime și este cel mai înalt din România.","Lacul are o suprafață de circa 390 ha și un volum de circa 210 milioane m³. Apa lui este dusă printr-o aducțiune subterană la hidrocentrala Retezat (335 MW), parte a amenajării hidroenergetice Râul Mare–Retezat. Drumul spre baraj urcă pe valea Râului Mare dinspre Râu de Mori."],"facts":[{"label":"Baraj","value":"168 m înălțime — cel mai înalt din România"},{"label":"Construcție","value":"1975–1986"},{"label":"Suprafața lacului","value":"~390 ha"},{"label":"Volum","value":"~210 milioane m³"},{"label":"Folosință","value":"Hidrocentrala Retezat (335 MW)"}]},"en":{"name":"Lake Gura Apelor","tagline":"The mountain lake behind Romania's tallest dam (168 m), at the entrance to Retezat National Park.","description":["Lake Gura Apelor formed behind the dam of the same name, built between 1975 and 1986 on the Râul Mare river, where it meets the Lăpușnicul Mare, Lăpușnicul Mic and Șes streams, about 40 km from Hațeg. The rock-fill dam with a clay core is 168 m high, the tallest in Romania.","The lake covers about 390 ha and holds some 210 million m³ of water, carried through an underground conduit to the Retezat hydropower plant (335 MW), part of the Râul Mare–Retezat hydro scheme. The road to the dam climbs the Râul Mare valley from Râu de Mori."],"facts":[{"label":"Dam","value":"168 m high — the tallest in Romania"},{"label":"Built","value":"1975–1986"},{"label":"Lake area","value":"~390 ha"},{"label":"Volume","value":"~210 million m³"},{"label":"Purpose","value":"Retezat hydropower plant (335 MW)"}]}},{"id":"pestera-cioclovina","name":"Peștera Cioclovina","category":{"ro":"Peșteră","en":"Cave"},"area":"Țara Hațegului","townId":"bosorod","coords":[45.5753,23.136],"hasReviews":true,"season":"vara","images":["images/placeholder.svg"],"ro":{"tagline":"Peștera în care a fost găsit craniul „Cioclovina 1”, unul dintre cei mai vechi oameni moderni din Europa Centrală și de Sud-Est.","description":["Peștera Cioclovina Uscată se află lângă satul Cioclovina (comuna Boșorod), în Munții Șureanu, pe teritoriul Parcului Natural Grădiștea Muncelului–Cioclovina, unde complexul carstic Ponorâci–Cioclovina este rezervație naturală. Este o galerie carstică de circa 2 km, cercetată încă din anii 1880; peștera vecină, Cioclovina cu Apă, este accesibilă doar speologilor.","Peștera a fost exploatată pentru guanofosfat — „fosfatul de Cioclovina”, un îngrășământ natural format din depozitele lăsate de lilieci. În timpul acestor lucrări a fost găsit, în 1941, craniul „Cioclovina 1”, datat cu radiocarbon la 28.000–29.000 de ani; analizele ADN au confirmat că a aparținut unui Homo sapiens. Între 1911 și 1921 au fost scoase de aici și numeroase fosile de urs de peșteră, iar în 1931 a fost descris din această peșteră un mineral nou, ardealitul, numit după Ardeal.","Până la peșteră se ajunge din satul Cioclovina, de unde mai sunt circa 6 km. Zona e străbătută și de traseul marcat Ohaba Ponor – Peștera Ponorici – Peștera Cioclovina – Boșorod."],"facts":[{"label":"Lungime","value":"~2 km (Peștera Cioclovina Uscată)"},{"label":"Descoperire","value":"craniul „Cioclovina 1” (1941), 28.000–29.000 de ani (radiocarbon)"},{"label":"Mineral","value":"localitatea-tip a ardealitului (descris în 1931)"},{"label":"Arie protejată","value":"Parcul Natural Grădiștea Muncelului–Cioclovina"},{"label":"Acces","value":"~6 km din satul Cioclovina (comuna Boșorod)"}]},"en":{"name":"Cioclovina Cave","tagline":"The cave where the \"Cioclovina 1\" skull was found — one of the oldest modern humans in Central and South-East Europe.","description":["Peștera Cioclovina Uscată (the \"dry\" Cioclovina Cave) lies near the village of Cioclovina (Boșorod commune), in the Șureanu Mountains, inside the Grădiștea Muncelului–Cioclovina Natural Park, where the Ponorâci–Cioclovina karst complex is a nature reserve. It is a karst gallery about 2 km long, studied since the 1880s; the neighbouring Cioclovina cu Apă (\"wet\") cave is open only to cavers.","The cave was mined for guano phosphate — \"Cioclovina phosphate\", a natural fertiliser formed from bat deposits. During this work, in 1941, the \"Cioclovina 1\" skull was found, radiocarbon-dated to 28,000–29,000 years; DNA analysis confirmed it belonged to a Homo sapiens. Numerous cave bear fossils were also recovered here between 1911 and 1921, and in 1931 a new mineral, ardealite — named after Ardeal, the Romanian name for Transylvania — was described from this cave.","The cave is reached from the village of Cioclovina, about 6 km away. The area is also crossed by the marked Ohaba Ponor – Ponorici Cave – Cioclovina Cave – Boșorod trail."],"facts":[{"label":"Length","value":"~2 km (Peștera Cioclovina Uscată)"},{"label":"Discovery","value":"the \"Cioclovina 1\" skull (1941), 28,000–29,000 years old (radiocarbon)"},{"label":"Mineral","value":"type locality of ardealite (described in 1931)"},{"label":"Protected area","value":"Grădiștea Muncelului–Cioclovina Natural Park"},{"label":"Access","value":"~6 km from Cioclovina village (Boșorod commune)"}]}},{"id":"pestera-zeicului","name":"Peștera Zeicului","category":{"ro":"Peșteră","en":"Cave"},"area":"Uricani","townId":"uricani","coords":[45.281,22.898],"hasReviews":true,"season":"vara","images":["images/pestera-zeicului.jpg"],"photoCredit":{"author":"Petr Vodička","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pestera_Zeicului.jpg"},"ro":{"tagline":"Rezervație speologică pe valea Jiului de Vest, în amonte de Câmpu lui Neag, cu una dintre cele mai mari stalactite din țară.","description":["Peștera Zeicului se deschide pe valea Jiului de Vest, în amonte de Câmpu lui Neag, lângă drumul DN66A, pe teritoriul Parcului Național Retezat. A fost declarată rezervație naturală speologică pentru marea varietate de formațiuni stalagmitice și pentru bogatul material paleontologic găsit aici, inclusiv urme de urs de cavernă.","Localnicii foloseau prima ei porțiune ca adăpost pentru turme, iar legenda spune că aici s-ar fi ascuns haiducii lui Zeicu — în peșteră s-au găsit flinte ruginite. După prima sală urmează un horn de 12 m și o sală bogată în concrețiuni, din care pornește un puț adânc de 48 m, cu o stalactită de peste 12 m, una dintre cele mai mari din România. Fiind rezervație, interiorul nu e amenajat pentru vizitare."],"facts":[{"label":"Localizare","value":"valea Jiului de Vest, lângă DN66A, în amonte de Câmpu lui Neag (orașul Uricani)"},{"label":"Statut","value":"rezervație speologică, în Parcul Național Retezat"},{"label":"Reper","value":"puț de 48 m cu o stalactită de peste 12 m"},{"label":"Descoperiri","value":"urme de urs de cavernă (Ursus spelaeus)"}]},"en":{"name":"Zeicu Cave","tagline":"A cave reserve in the Western Jiu valley, upstream of Câmpu lui Neag, with one of the largest stalactites in the country.","description":["Zeicu Cave opens onto the Western Jiu valley upstream of Câmpu lui Neag, by the DN66A road, inside Retezat National Park. It was declared a speleological reserve for its wide variety of stalagmite formations and its rich palaeontological finds, including traces of cave bears.","Locals used its first section to shelter their flocks, and legend says the outlaws of Zeicu hid here — rusty flintlocks were found in the cave. Past the first chamber comes a 12 m chimney and a chamber rich in formations, from which a 48 m shaft drops, holding a stalactite more than 12 m long, one of the largest in Romania. As a reserve, the interior is not set up for visitors."],"facts":[{"label":"Location","value":"Western Jiu valley, by the DN66A, upstream of Câmpu lui Neag (Uricani town)"},{"label":"Status","value":"speleological reserve, in Retezat National Park"},{"label":"Highlight","value":"48 m shaft with a stalactite over 12 m long"},{"label":"Finds","value":"cave bear remains (Ursus spelaeus)"}]}},{"id":"lacul-valea-de-pesti","name":"Lacul Valea de Pești","category":{"ro":"Lac de acumulare","en":"Reservoir lake"},"area":"Uricani","townId":"uricani","coords":[45.3003,23.0588],"hasReviews":true,"season":"vara","images":["images/lacul-valea-de-pesti.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Barajul_Valea_de_Pe%C8%99ti.JPG"},"ro":{"tagline":"Lac de munte de 2,5 km în spatele unui baraj de 56 m, lângă Câmpu lui Neag — rezerva de apă a Văii Jiului.","description":["Barajul Valea de Pești a fost construit între 1967 și 1973 pe râul cu același nume, lângă Câmpu lui Neag, și are 56 m înălțime. În spatele lui s-a format un lac de acumulare lung de 2,5 km, cu o suprafață de 31 ha, adânc de până la 53 m, la 830 m altitudine.","Lacul alimentează cu apă Valea Jiului, iar la ape mari ajută la producerea de energie și la atenuarea viiturilor. În apele lui trăiesc știucă, somn, crap, mreană și clean. Pe lângă lac trece drumul transmontan nou spre Runcu (Gorj), prin Cheile Sohodolului."],"facts":[{"label":"Baraj","value":"56 m înălțime, construit 1967–1973"},{"label":"Lac","value":"31 ha, 2,5 km lungime, adâncime maximă 53 m"},{"label":"Altitudine","value":"830 m"},{"label":"Folosință","value":"alimentarea cu apă a Văii Jiului"},{"label":"Localizare","value":"lângă Câmpu lui Neag, orașul Uricani"}]},"en":{"name":"Lake Valea de Pești","tagline":"A 2.5 km mountain lake behind a 56 m dam near Câmpu lui Neag — the Jiu Valley's water reserve.","description":["The Valea de Pești dam was built between 1967 and 1973 on the river of the same name, near Câmpu lui Neag, and stands 56 m high. Behind it lies a reservoir 2.5 km long, covering 31 ha and up to 53 m deep, at 830 m above sea level.","The lake supplies water to the Jiu Valley, and at high water it also helps generate power and soften floods. Pike, catfish, carp, barbel and chub live in it. The new mountain road to Runcu (Gorj), through the Sohodol Gorges, runs past the lake."],"facts":[{"label":"Dam","value":"56 m high, built 1967–1973"},{"label":"Lake","value":"31 ha, 2.5 km long, up to 53 m deep"},{"label":"Altitude","value":"830 m"},{"label":"Use","value":"water supply for the Jiu Valley"},{"label":"Location","value":"near Câmpu lui Neag, Uricani town"}]}},{"id":"cheile-crivadiei","name":"Cheile Crivadiei","category":{"ro":"Rezervație naturală","en":"Nature reserve"},"area":"Bănița","townId":"banita","coords":[45.4689,23.2144],"hasReviews":true,"season":"tot-anul","images":["images/cheile-crivadiei.jpg"],"photoCredit":{"author":"Zsolt deak","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Turn_de_cetate_(ruine).JPG"},"ro":{"tagline":"Rezervație de 10 ha din Parcul Natural Grădiștea Muncelului-Cioclovina, lângă ruinele Turnului Crivadiei.","description":["Cheile Crivadiei sunt o arie protejată de interes național (categoria a IV-a IUCN, rezervație de tip mixt), aflată pe raza Parcului Natural Grădiștea Muncelului-Cioclovina, lângă satul Crivadia din comuna Bănița. Rezervația are 10 ha și se remarcă prin frumusețea peisajului și printr-o floră bogată și variată.","La adăpostul abruptului cheilor, pe substrat calcaros, a rămas o adevărată „oază” termofilă, cu numeroase elemente dacice. În imediata apropiere se află monumentul feudal Turnul Crivadiei — ruinele lui apar în fotografia alăturată —, iar în sat există și Peștera Gaura Oanei."],"facts":[{"label":"Suprafață","value":"10 ha"},{"label":"Statut","value":"arie protejată de interes național, categoria a IV-a IUCN"},{"label":"Localizare","value":"lângă satul Crivadia, comuna Bănița"},{"label":"Reper","value":"Turnul Crivadiei, monument feudal"}]},"en":{"name":"Crivadia Gorge","tagline":"A 10 ha reserve in the Grădiștea Muncelului-Cioclovina Natural Park, beside the ruins of the Crivadia Tower.","description":["The Crivadia Gorge is a nationally protected area (IUCN category IV, mixed-type reserve) within the Grădiștea Muncelului-Cioclovina Natural Park, near the village of Crivadia in Bănița commune. The reserve covers 10 ha and stands out for its scenery and its rich, varied flora.","Sheltered by the steep walls of the gorge, on limestone, survives a true thermophilous “oasis” with many Dacian elements. Close by stands the medieval Crivadia Tower — its ruins appear in the accompanying photo — and the village also has the Gaura Oanei Cave."],"facts":[{"label":"Area","value":"10 ha"},{"label":"Status","value":"nationally protected area, IUCN category IV"},{"label":"Location","value":"near Crivadia village, Bănița commune"},{"label":"Landmark","value":"Crivadia Tower, a medieval monument"}]}},{"id":"podul-natural-grohot","name":"Podul natural de la Grohot","category":{"ro":"Monument al naturii","en":"Natural monument"},"area":"Țara Zarandului","townId":"bulzestii-de-sus","coords":[46.233,22.75],"hasReviews":true,"season":"tot-anul","images":["images/placeholder.svg"],"ro":{"tagline":"Monument al naturii pe valea Uibăreștilor, la circa 15 km de Țebea, ocrotit pentru podul natural și vegetația de pe calcar.","description":["Podul natural de la Grohot este o rezervație naturală de tip geologic (categoria a III-a IUCN, monument al naturii), cu o suprafață de 1 ha, aflată pe valea Uibăreștilor, pe teritoriul satului Grohot, comuna Bulzeștii de Sus, la circa 15 km de Țebea.","Este ocrotit pentru elementele naturale specifice — podul natural propriu-zis —, la care se adaugă vegetația dezvoltată pe substrat calcaros, cu numeroase elemente specifice zonei submediteraneene."],"facts":[{"label":"Suprafață","value":"1 ha"},{"label":"Statut","value":"rezervație geologică, monument al naturii (categoria a III-a IUCN)"},{"label":"Localizare","value":"valea Uibăreștilor, satul Grohot, comuna Bulzeștii de Sus"},{"label":"Distanță","value":"~15 km de Țebea"}]},"en":{"name":"Grohot Natural Bridge","tagline":"A natural monument in the Uibărești valley, about 15 km from Țebea, protected for its natural bridge and limestone vegetation.","description":["The Grohot Natural Bridge is a geological nature reserve (IUCN category III, natural monument) of 1 ha, in the Uibărești valley, in the village of Grohot, Bulzeștii de Sus commune, about 15 km from Țebea.","It is protected for its specific natural features — the natural bridge itself — together with the vegetation growing on limestone, with many elements typical of the sub-Mediterranean zone."],"facts":[{"label":"Area","value":"1 ha"},{"label":"Status","value":"geological reserve, natural monument (IUCN category III)"},{"label":"Location","value":"Uibărești valley, Grohot village, Bulzeștii de Sus commune"},{"label":"Distance","value":"~15 km from Țebea"}]}},{"id":"cascada-clocota","name":"Cascada Clocota","category":{"ro":"Cascadă","en":"Waterfall"},"area":"Geoagiu","townId":"geoagiu","coords":[45.9374,23.1679],"hasReviews":true,"season":"tot-anul","relatedIds":["statiunea-geoagiu-bai"],"images":["images/cascada-clocota.jpg"],"photoCredit":{"author":"Oguszt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Waterfall_geoagiu.jpg"},"ro":{"tagline":"Mică cascadă pe râul Clocota, aproape de centrul stațiunii Geoagiu-Băi.","description":["Cascada Clocota se află în partea sud-estică a stațiunii Geoagiu-Băi, aproape de centru, și se formează pe râul Clocota. Deși nu are dimensiuni mari, impresionează prin cădere și prin amplasament.","Se poate ajunge pe două căi: pe poteca care coboară din drumul spre orașul Geoagiu sau prin stațiune, pe o stradă îngustă care pornește din drumul dintre Hotelul Diana și centrul civic al stațiunii."],"facts":[{"label":"Localizare","value":"sud-estul stațiunii Geoagiu-Băi, lângă centru"},{"label":"Râu","value":"Clocota"},{"label":"Acces","value":"pe potecă din drumul spre Geoagiu sau pe o stradă îngustă din stațiune"}]},"en":{"name":"Clocota Waterfall","tagline":"A small waterfall on the Clocota stream, close to the centre of Geoagiu-Băi resort.","description":["The Clocota Waterfall lies in the south-eastern part of Geoagiu-Băi resort, close to the centre, and forms on the Clocota stream. Though not large, it is impressive for its drop and its setting.","It can be reached two ways: along the path that descends from the road to Geoagiu town, or through the resort, along a narrow street that leaves the road between the Hotel Diana and the civic centre."],"facts":[{"label":"Location","value":"south-east of Geoagiu-Băi resort, near the centre"},{"label":"Stream","value":"Clocota"},{"label":"Access","value":"by path from the road to Geoagiu, or via a narrow street in the resort"}]}},{"id":"cheile-cernei","name":"Cheile Cernei","category":{"ro":"Rezervație naturală","en":"Nature reserve"},"area":"Poiana Ruscă","townId":"hunedoara","coords":[45.6539,22.6589],"hasReviews":true,"season":"tot-anul","relatedIds":["lacul-cincis"],"images":["images/cheile-cernei.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Cheile_Cernei.JPG"},"ro":{"tagline":"Chei de 2 ha săpate de râul Cerna în șisturile cristaline ale Munților Poiana Ruscă.","description":["Cheile Cernei sunt o arie naturală protejată de interes național (categoria a IV-a IUCN, rezervație de tip mixt) pe valea Cernei, pe raza comunei Lunca Cernii de Jos, în Munții Poiana Ruscă. Rezervația, de 2 ha, este o formațiune geomorfologică de chei, cu versanți înalți, săpată de apele râului Cerna în roci metamorfice (șisturi cristaline).","Râul Cerna izvorăște din Poiana Ruscă, străbate Ținutul Pădurenilor, alimentează Lacul Cincis și trece prin Hunedoara, înainte de a se vărsa în Mureș."],"facts":[{"label":"Suprafață","value":"2 ha"},{"label":"Statut","value":"arie protejată de interes național, categoria a IV-a IUCN"},{"label":"Rocă","value":"șisturi cristaline (roci metamorfice)"},{"label":"Localizare","value":"valea Cernei, comuna Lunca Cernii de Jos, Munții Poiana Ruscă"}]},"en":{"name":"Cerna Gorge","tagline":"A 2 ha gorge cut by the Cerna river through the crystalline schists of the Poiana Ruscă Mountains.","description":["The Cerna Gorge is a nationally protected natural area (IUCN category IV, mixed-type reserve) in the Cerna valley, in Lunca Cernii de Jos commune, in the Poiana Ruscă Mountains. The 2 ha reserve is a geomorphological gorge formation with high slopes, cut by the waters of the Cerna river through metamorphic rock (crystalline schists).","The Cerna rises in the Poiana Ruscă, crosses the Pădureni Land, feeds Lake Cincis and passes through Hunedoara before flowing into the Mureș."],"facts":[{"label":"Area","value":"2 ha"},{"label":"Status","value":"nationally protected area, IUCN category IV"},{"label":"Rock","value":"crystalline schists (metamorphic rock)"},{"label":"Location","value":"Cerna valley, Lunca Cernii de Jos commune, Poiana Ruscă Mountains"}]}},{"id":"pestera-cu-corali","name":"Peștera cu Corali","category":{"ro":"Peșteră","en":"Cave"},"area":"Vâlcan","hasReviews":true,"season":"tot-anul","images":["images/pestera-cu-corali.jpg"],"photoCredit":{"author":"Petr Vodička","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pestera_cu_Corali.jpg"},"ro":{"tagline":"Peșteră-rezervație din Munții Vâlcan, cu o sală de coralite; închisă accesului public din 1972.","description":["Peștera cu Corali se află în Munții Vâlcan, pe valea Scorotei, la circa 12 km de Câmpu lui Neag, la aproximativ 1000 m altitudine, sub culmea Cioaca. A fost descoperită în 1970 de membri ai clubului de speologie „Focul Viu” din București; planul ei s-a întocmit un an mai târziu, iar în 1972 a fost declarată rezervație speologică și închisă accesului publicului.","Este o peșteră liniară, fosilă și descendentă, lungă de 83 m. O galerie înaltă de 2–4 m se îngustează la 1 m într-un punct numit Altarul; după aproximativ 50 m urmează o săritoare de 5 m, la baza căreia începe Sala cu Coralite, lungă de 30 m. Fiind rezervație, nu se poate vizita."],"facts":[{"label":"Lungime","value":"83 m"},{"label":"Altitudine","value":"~1000 m, sub culmea Cioaca"},{"label":"Descoperire","value":"1970, de clubul de speologie „Focul Viu” din București"},{"label":"Statut","value":"rezervație speologică din 1972; acces interzis publicului"},{"label":"Localizare","value":"valea Scorotei, la ~12 km de Câmpu lui Neag"}]},"en":{"name":"Coral Cave","tagline":"A cave reserve in the Vâlcan Mountains with a chamber of coralloid formations; closed to the public since 1972.","description":["Coral Cave lies in the Vâlcan Mountains, in the Scorota valley, about 12 km from Câmpu lui Neag, at roughly 1,000 m altitude, below the Cioaca ridge. It was discovered in 1970 by members of the “Focul Viu” caving club of Bucharest; its plan was drawn up a year later, and in 1972 it was declared a speleological reserve and closed to the public.","It is a linear, fossil, descending cave 83 m long. A gallery 2–4 m high narrows to 1 m at a spot called the Altar; after about 50 m comes a 5 m drop, at whose foot begins the 30 m-long Coralite Chamber. As a reserve, it cannot be visited."],"facts":[{"label":"Length","value":"83 m"},{"label":"Altitude","value":"~1,000 m, below the Cioaca ridge"},{"label":"Discovery","value":"1970, by the “Focul Viu” caving club of Bucharest"},{"label":"Status","value":"speleological reserve since 1972; closed to the public"},{"label":"Location","value":"Scorota valley, ~12 km from Câmpu lui Neag"}]}},{"id":"padurea-slivut","name":"Pădurea Slivuț","category":{"ro":"Rezervație naturală","en":"Nature reserve"},"area":"Hațeg","townId":"hateg","coords":[45.625,22.9775],"hasReviews":true,"season":"tot-anul","images":["images/hateg-rezervatia-zimbri.jpg"],"photoCredit":{"author":"Radu Niculița","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:14-18-hateg-zimbrii-2.jpg"},"ro":{"tagline":"Pădure de stejari de 40 ha lângă Hațeg, cu rezervație de zimbri din 1958.","description":["Pădurea Slivuț este o arie protejată de interes național (categoria a IV-a IUCN, rezervație botanică), de 40 ha, aflată lângă orașul Hațeg și inclusă în Geoparcul Dinozaurilor „Țara Hațegului”. Este un ecosistem natural de stejărete xerofile, rest al unor întinse păduri inițiale de stejar, defrișate odată cu extinderea agriculturii pe dealurile din marginea depresiunii Hațegului.","Din 1958, în pădure funcționează o rezervație de zimbri, aflată în custodia Direcției Silvice Deva, prin Ocolul Silvic Hațeg."],"facts":[{"label":"Suprafață","value":"40 ha"},{"label":"Statut","value":"arie protejată de interes național, categoria a IV-a IUCN; în Geoparcul Dinozaurilor"},{"label":"Zimbri","value":"rezervație din 1958, în custodia Ocolului Silvic Hațeg"},{"label":"Localizare","value":"lângă orașul Hațeg"}]},"en":{"name":"Slivuț Forest","tagline":"A 40 ha oak forest near Hațeg, with a European bison reserve since 1958.","description":["Slivuț Forest is a nationally protected area (IUCN category IV, botanical reserve) of 40 ha near the town of Hațeg, included in the “Hațeg Country” Dinosaur Geopark. It is a natural ecosystem of xerophilous oak woods, a remnant of vast original oak forests cleared as farming spread over the hills at the edge of the Hațeg depression.","Since 1958 a European bison reserve has operated in the forest, in the custody of the Deva Forestry Directorate through the Hațeg Forest District."],"facts":[{"label":"Area","value":"40 ha"},{"label":"Status","value":"nationally protected area, IUCN category IV; within the Dinosaur Geopark"},{"label":"Bison","value":"reserve since 1958, in the custody of the Hațeg Forest District"},{"label":"Location","value":"near the town of Hațeg"}]}},{"id":"cascada-lolaia","name":"Cascada Lolaia","category":{"ro":"Cascadă","en":"Waterfall"},"area":"Parcul Național Retezat","townId":"hateg","coords":[45.4259,22.8973],"hasReviews":true,"season":"tot-anul","images":["images/cascada-lolaia.jpg"],"photoCredit":{"author":"Raimond Spekking","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascada_Lolaia-9087.jpg"},"ro":{"tagline":"Cădere de circa 15 m pe valea Nucșoarei, la o plimbare scurtă de popasul Cârnic, în Parcul Național Retezat.","description":["Cascada Lolaia se află în Parcul Național Retezat, pe valea Nucșoarei, și este cunoscută turiștilor care urcă sau coboară pe aici spre zona Pietrele. Apa cade de la un prag de aproximativ 15 m, rupându-se în două fâșii, la capătul unei porțiuni de chei aflate pe la circa 1.000 m altitudine.","Drumul asfaltat dinspre Hațeg (prin Ohaba de Sub Piatră, Sălașu de Jos, Sălașu de Sus, Mălăiești și Nucșoara) ajunge aproape de popasul Cârnic, unde se lasă mașina. De acolo, cascada se află la circa 15–20 de minute de mers pe jos; poate fi privită din față, de pe poteca cu trepte de lemn, sau de sus, de pe o pasarelă peste râul Pietrele."],"facts":[{"label":"Înălțimea căderii","value":"circa 15 m"},{"label":"Altitudine","value":"circa 1.000 m"},{"label":"Localizare","value":"valea Nucșoarei, Parcul Național Retezat"},{"label":"Acces","value":"circa 15–20 de minute pe jos de la popasul Cârnic"}]},"en":{"name":"Lolaia Waterfall","tagline":"A drop of about 15 m on the Nucșoara valley, a short walk from the Cârnic stop in Retezat National Park.","description":["The Lolaia Waterfall lies in Retezat National Park, on the Nucșoara valley, and is well known to hikers going up or down towards the Pietrele area. The water falls from a ledge of about 15 m, splitting into two ribbons, at the end of a stretch of gorge at around 1,000 m altitude.","The paved road from Hațeg (through Ohaba de Sub Piatră, Sălașu de Jos, Sălașu de Sus, Mălăiești and Nucșoara) reaches close to the Cârnic stop, where cars are left. From there the waterfall is about a 15–20 minute walk; it can be viewed from the front, from the path with wooden steps, or from above, from a footbridge over the Pietrele river."],"facts":[{"label":"Height of the drop","value":"about 15 m"},{"label":"Altitude","value":"about 1,000 m"},{"label":"Location","value":"Nucșoara valley, Retezat National Park"},{"label":"Access","value":"about 15–20 minutes on foot from the Cârnic stop"}]}}];
